/**
 * @file dailyLoginSystem.ts
 * 7-day login calendar with freeze mode (missed days keep the same tier).
 */

import { DAILY_LOGIN_REWARDS, type DailyLoginReward } from './constants/balance/dailyLoginCalendar.ts';
import type { GameRuntime } from './src/types/game.js';
import type { QuestRewardLine } from './src/bus/snapshots.js';
import { publishQuestsChanged, publishResourcesChanged } from './src/bus/publishHooks.ts';
import { callGame, callGameNumber, callGameVoid } from './src/lib/callBound.ts';
import { buildDailyLoginRewardLines } from './src/lib/dailyLoginRewardLines.ts';
import { getQuestBadgeRewardMultiplier } from './questSystem.ts';
import { recordPokedollarsEarned } from './src/lib/pokedollarsEconomyTracking.js';

export interface DailyLoginCalendarState {
    dayIndex: number;
    lastClaimDateKey: string;
}

export interface DailyLoginDaySnapshot {
    index: number;
    label: string;
    rewards: QuestRewardLine[];
    state: 'claimed' | 'current' | 'future';
    canClaim: boolean;
}

export interface DailyLoginSnapshot {
    unlocked: boolean;
    canClaimToday: boolean;
    dayIndex: number;
    days: DailyLoginDaySnapshot[];
    title: string;
    claimLabel: string;
    claimedTodayLabel: string;
    freezeHint: string;
}

export function getTodayDateKey(now = new Date()): string {
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
}

function parseDateKey(key: string): Date | null {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(key)) return null;
    const [y, m, d] = key.split('-').map(Number);
    if (!y || !m || !d) return null;
    return new Date(y, m - 1, d);
}

function daysBetweenKeys(fromKey: string, toKey: string): number {
    const from = parseDateKey(fromKey);
    const to = parseDateKey(toKey);
    if (!from || !to) return 0;
    const ms = to.getTime() - from.getTime();
    return Math.floor(ms / (24 * 60 * 60 * 1000));
}

export function ensureDailyLoginState(game: GameRuntime): DailyLoginCalendarState {
    if (!game.dailyLoginCalendar || typeof game.dailyLoginCalendar !== 'object') {
        game.dailyLoginCalendar = { dayIndex: 0, lastClaimDateKey: '' };
    }
    const state = game.dailyLoginCalendar;
    if (!Number.isFinite(Number(state.dayIndex))) state.dayIndex = 0;
    state.dayIndex = Math.max(0, Math.min(6, Math.floor(Number(state.dayIndex))));
    if (typeof state.lastClaimDateKey !== 'string') state.lastClaimDateKey = '';
    return state;
}

export function isDailyLoginUnlocked(game: GameRuntime): boolean {
    return !!(game.unlockedFeatures && game.unlockedFeatures.classicQuests);
}

export function canClaimDailyLoginToday(game: GameRuntime, now = new Date()): boolean {
    if (!isDailyLoginUnlocked(game)) return false;
    const state = ensureDailyLoginState(game);
    const today = getTodayDateKey(now);
    if (!state.lastClaimDateKey) return true;
    return state.lastClaimDateKey !== today;
}

/** Effective amounts after mastery scalers (same pipeline as claim). */
export interface ScaledDailyLoginReward {
    pokedollars?: number;
    questTokens?: number;
    essenceDust?: number;
    combatTickets?: number;
    triumphMarks?: number;
    eggs?: DailyLoginReward['eggs'];
    items?: Record<string, number>;
}

function scaleDailyLoginAmountByBadges(amount: number, badgeMult: number): number {
    const n = Math.max(0, Math.floor(Number(amount) || 0));
    if (n <= 0) return 0;
    return Math.floor(n * badgeMult);
}

/** @internal Vitest */
export function computeScaledDailyLoginReward(
    game: GameRuntime,
    reward: DailyLoginReward,
): ScaledDailyLoginReward {
    const scaleDaily = (n: number) => callGameNumber(game, game['scaleMasteryDailyLoginRewardAmount'], n);
    const badgeMult = getQuestBadgeRewardMultiplier(game);
    const scaled: ScaledDailyLoginReward = {};

    if (reward.pokedollars) {
        const amt = scaleDailyLoginAmountByBadges(scaleDaily(reward.pokedollars), badgeMult);
        if (amt > 0) scaled.pokedollars = amt;
    }
    if (reward.questTokens) {
        const tokenReward = callGameNumber(game, game['scaleMasteryQuestTokenAmount'], reward.questTokens);
        const tokens = scaleDailyLoginAmountByBadges(scaleDaily(tokenReward), badgeMult);
        if (tokens > 0) scaled.questTokens = tokens;
    }
    if (reward.essenceDust) {
        const dust = scaleDailyLoginAmountByBadges(scaleDaily(reward.essenceDust), badgeMult);
        if (dust > 0) scaled.essenceDust = dust;
    }
    if (reward.combatTickets) {
        const tickets = callGameNumber(game, game['scaleMasteryCombatTicketAmount'], reward.combatTickets);
        const scaledTickets = scaleDailyLoginAmountByBadges(scaleDaily(tickets), badgeMult);
        if (scaledTickets > 0) scaled.combatTickets = scaledTickets;
    }
    if (reward.triumphMarks) {
        let marks = scaleDaily(reward.triumphMarks);
        marks = callGameNumber(game, game['scaleMasteryTriumphMarksAmount'], marks, marks);
        marks = scaleDailyLoginAmountByBadges(marks, badgeMult);
        if (marks > 0) scaled.triumphMarks = marks;
    }
    if (reward.eggs) {
        const eggs = reward.eggs;
        scaled.eggs = {
            common: eggs.common ? scaleDailyLoginAmountByBadges(eggs.common, badgeMult) : undefined,
            rare: eggs.rare ? scaleDailyLoginAmountByBadges(eggs.rare, badgeMult) : undefined,
            epic: eggs.epic ? scaleDailyLoginAmountByBadges(eggs.epic, badgeMult) : undefined,
            legendary: eggs.legendary ? scaleDailyLoginAmountByBadges(eggs.legendary, badgeMult) : undefined,
        };
    }
    if (reward.items) {
        const items: Record<string, number> = {};
        for (const [itemKey, count] of Object.entries(reward.items)) {
            const qty = scaleDailyLoginAmountByBadges(Math.floor(Number(count) || 0), badgeMult);
            if (qty > 0) items[itemKey] = qty;
        }
        if (Object.keys(items).length > 0) scaled.items = items;
    }

    return scaled;
}

function applyDailyLoginReward(game: GameRuntime, reward: DailyLoginReward): void {
    const scaled = computeScaledDailyLoginReward(game, reward);
    if (scaled.pokedollars) {
        game.pokedollars = (game.pokedollars || 0) + scaled.pokedollars;
        recordPokedollarsEarned(game, scaled.pokedollars);
    }
    if (scaled.questTokens) {
        game.questTokens = (game.questTokens || 0) + scaled.questTokens;
        if (game.stats) {
            game.stats.totalQuestTokensEarned = (game.stats.totalQuestTokensEarned || 0) + scaled.questTokens;
        }
    }
    if (scaled.essenceDust) {
        game.essenceDust = (game.essenceDust || 0) + scaled.essenceDust;
    }
    if (scaled.combatTickets) {
        game.combatTickets = (game.combatTickets || 0) + scaled.combatTickets;
    }
    if (scaled.triumphMarks) {
        game.triumphMarks = (game.triumphMarks || 0) + scaled.triumphMarks;
    }
    const eggs = scaled.eggs;
    if (eggs && game.eggs) {
        if (eggs.common) game.eggs.common = (game.eggs.common || 0) + eggs.common;
        if (eggs.rare) game.eggs.rare = (game.eggs.rare || 0) + eggs.rare;
        if (eggs.epic) game.eggs.epic = (game.eggs.epic || 0) + eggs.epic;
        if (eggs.legendary) game.eggs.legendary = (game.eggs.legendary || 0) + eggs.legendary;
    }
    if (scaled.items) {
        for (const [itemKey, count] of Object.entries(scaled.items)) {
            if (count <= 0) continue;
            if (typeof game.addItem === 'function') {
                game.addItem(itemKey, count, false);
            } else if (game.items && typeof game.items === 'object') {
                game.items[itemKey] = (Number(game.items[itemKey]) || 0) + count;
            }
        }
    }
}

export function claimDailyLoginRewardLogic(game: GameRuntime, now = new Date()): boolean {
    if (!canClaimDailyLoginToday(game, now)) return false;

    const state = ensureDailyLoginState(game);
    const today = getTodayDateKey(now);
    const reward = DAILY_LOGIN_REWARDS[state.dayIndex];
    if (!reward) return false;

    const claimedDayNum = state.dayIndex + 1;
    applyDailyLoginReward(game, reward);
    state.lastClaimDateKey = today;

    if (state.dayIndex >= 6) {
        state.dayIndex = 0;
    } else {
        state.dayIndex += 1;
    }

    callGameVoid(game, game['saveGame']);
    callGame<void>(game, game['logMessage'], game.t('dailyLogin.claimedToast', { day: claimedDayNum }));
    publishResourcesChanged();
    publishQuestsChanged();
    return true;
}

export function getDailyLoginSnapshot(game: GameRuntime, now = new Date()): DailyLoginSnapshot {
    const unlocked = isDailyLoginUnlocked(game);
    const state = ensureDailyLoginState(game);
    const canClaimToday = canClaimDailyLoginToday(game, now);
    const today = getTodayDateKey(now);

    const justClaimedIndex = state.lastClaimDateKey === today
        ? (state.dayIndex === 0 ? 6 : state.dayIndex - 1)
        : -1;

    const days: DailyLoginDaySnapshot[] = DAILY_LOGIN_REWARDS.map((reward, index) => {
        let dayState: DailyLoginDaySnapshot['state'] = 'future';
        if (index < state.dayIndex || index === justClaimedIndex) {
            dayState = 'claimed';
        } else if (index === state.dayIndex) {
            dayState = 'current';
        }

        const canClaim = unlocked && dayState === 'current' && canClaimToday;
        const scaled = computeScaledDailyLoginReward(game, reward);
        return {
            index,
            label: game.t('dailyLogin.dayN', { n: index + 1 }),
            rewards: buildDailyLoginRewardLines(game, scaled),
            state: dayState,
            canClaim,
        };
    });

    const badgeMult = getQuestBadgeRewardMultiplier(game);
    let freezeHint = game.t('dailyLogin.freezeHint');
    if (badgeMult > 1) {
        freezeHint += ` ${game.t('dailyLogin.badgeMultHint', { count: badgeMult })}`;
    }

    return {
        unlocked,
        canClaimToday: unlocked && canClaimToday,
        dayIndex: state.dayIndex,
        days,
        title: game.t('dailyLogin.title'),
        claimLabel: game.t('dailyLogin.claim'),
        claimedTodayLabel: game.t('dailyLogin.claimedToday'),
        freezeHint,
    };
}

/** @internal Vitest — simulate calendar progression without real time. */
export function _setDailyLoginStateForTest(
    game: GameRuntime,
    dayIndex: number,
    lastClaimDateKey: string,
): void {
    game.dailyLoginCalendar = { dayIndex, lastClaimDateKey };
}

/** @internal Vitest */
export function _shiftTodayKeyForTest(baseKey: string, deltaDays: number): string {
    const d = parseDateKey(baseKey);
    if (!d) return baseKey;
    d.setDate(d.getDate() + deltaDays);
    return getTodayDateKey(d);
}

/** Freeze mode: gap does not change dayIndex (only documented; logic is implicit). */
export function _daysSinceLastClaim(game: GameRuntime, now = new Date()): number {
    const state = ensureDailyLoginState(game);
    if (!state.lastClaimDateKey) return 0;
    return daysBetweenKeys(state.lastClaimDateKey, getTodayDateKey(now));
}
