/// <reference types="svelte" />
/**
 * Store: daily login calendar snapshot
 */

import { game } from '../../gameManager.js';
import type { GameRuntime } from '../types/game.js';
import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import {
  getDailyLoginSnapshot,
  type DailyLoginSnapshot,
} from '@snapshot-deps/dailyLogin';

const EMPTY: DailyLoginSnapshot = {
  unlocked: false,
  canClaimToday: false,
  dayIndex: 0,
  days: [],
  title: '',
  claimLabel: '',
  claimedTodayLabel: '',
  freezeHint: '',
};

function refresh(): DailyLoginSnapshot {
  const g = game as GameRuntime | null;
  if (!g || typeof g.t !== 'function') return EMPTY;
  return getDailyLoginSnapshot(g);
}

class DailyLoginStore {
  snapshot: DailyLoginSnapshot = $state(EMPTY);
  refresh(): void {
    this.snapshot = refresh();
  }
}

export const dailyLogin = new DailyLoginStore();

facade.subscribe(Evt.QUESTS_CHANGED, () => {
  dailyLogin.refresh();
});

facade.subscribe(Evt.RESOURCES_CHANGED, () => {
  dailyLogin.refresh();
});

facade.subscribe(Evt.SAFE_LOADED, () => {
  dailyLogin.refresh();
});
